 "content": "def transform(grid):
    # Each solid 2x2 square is one tile (color 1); the remaining cells form
    # three L-triomino tiles, colored by their relative position in the figure.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    out = [[0] * w for _ in range(h)]
    # Identify disjoint 2x2 squares, choosing top-left to bottom-right.
    used = set()
    for r in range(h - 1):
        for c in range(w - 1):
            cells = {(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
            if all(g[y][x] == 8 for y,x in cells) and not (cells & used):
                for y,x in cells: out[y][x] = 1
                used |= cells
    rem = {(r,c) for r in range(h) for c in range(w) if g[r][c] == 8 and (r,c) not in used}
    # Connected remaining groups are L-shaped triominoes; assign stable colors
    # in reading order, matching the three non-square tile roles.
    groups = []
    while rem:
        seed = min(rem)
        comp, stack = {seed}, [seed]
        rem.remove(seed)
        while stack:
            y,x = stack.pop()
            for p in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                if p in rem:
                    rem.remove(p); comp.add(p); stack.append(p)
        groups.append(comp)
    groups.sort(key=lambda z: (min(y for y,x in z), min(x for y,x in z)))
    # Color tile roles using the observed reading-order palette.
    for color, comp in zip((2,3,4), groups):
        for y,x in comp: out[y][x] = color
    return out
"
